import React, { useState, useEffect } from 'react';

function DisplayFoodTruck() {
  const [vendors, setVendors] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchVendors();
  }, []);

  const fetchVendors = async () => {
    try {
      const response = await fetch('http://localhost:8080/getAllVendors', {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
      });

      if (response.ok) {
        const data = await response.json();
        setVendors(data);
      } else {
        console.error('Error fetching vendors');
      }
    } catch (error) {
      console.error('Error:', error);
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return <div>Loading...</div>;
  }

  return (
    <div className="display-vendors-container">
      <h2>Submitted Food Truck Vendor Applications</h2>
      
      {vendors.length === 0 ? (
        <p>No vendor applications found.</p>
      ) : (
        <table className="vendors-table">
          <thead>
            <tr>
              <th>ID</th>
              <th>Name</th>
              <th>Cuisine Specialties</th>
              <th>Operating Region</th>
              <th>Menu Highlights</th>
              <th>Phone Number</th>
            </tr>
          </thead>
          <tbody>
            {vendors.map((vendor) => (
              <tr key={vendor.id}>
                <td>{vendor.id}</td>
                <td>{vendor.name}</td>
                <td>{vendor.cuisineSpecialties}</td>
                <td>{vendor.operatingRegion}</td>
                <td>{vendor.menuHighlights}</td>
                <td>{vendor.phoneNumber}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
}

export default DisplayFoodTruck;
